lishAdvancedWord("long-term consequences of argumentative architecture", "التبعات بعيدة المدى لـ البنية الحجاجية"),EnglishAdvancedWord("epistemic ambiguity in argumentative architecture", "الغموض المعرفي في البنية الحجاجية"),EnglishAdvancedWord("rhetorical subtext of argumentative architecture", "الدلالة البلاغية الضمنية لـ البنية الحجاجية")],
