      extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("methodological integrity of disciplined scholarly doubt", "النزاهة المنهجية لـ الشك العلمي المنضبط"),EnglishAdvancedWord("disciplinary disagreement over disciplined scholarly doubt", "الخلاف التخصصي حول الشك العلمي المنضبط"),EnglishAdvancedWord("counterfactual scenario for disciplined scholarly doubt", "السيناريو المضاد للواقع بشأن الشك العلمي المنضبط"),EnglishAdvancedWord("distributional trade-offs in disciplined scholarly doubt", "المفاضلات التوزيعية في الشك العلمي المنضبط"),EnglishAdvancedWord("independently corroborated findings on disciplined scholarly doubt", "النتائج المؤيدة بشكل مستقل بشأن الشك العلمي المنضبط"),EnglishAdvancedWord("normative presuppositions about disciplined scholarly doubt", "المسلمات المعيارية بشأن الشك العلمي المنضبط"),EnglishAdvancedWord("interdisciplinary perspectives on disciplined scholarly doubt", "الرؤى متعددة التخصصات بشأن الشك العلمي المنضبط"),EnglishAdvancedWord("institutional legitimacy in disciplined scholarly doubt", "المشروعية المؤسسية في الشك العلمي المنضبط"),EnglishAdvancedWord("qualitative triangulation of disciplined scholarly doubt", "التثليث النوعي لـ الشك العلمي المنضبط"),EnglishAdvancedWord("quantified uncertainty surrounding disciplined scholarly doubt", "عدم اليقين الكمي المحيط بـ الشك العلمي المنضبط"),EnglishAdvancedWord("contextual evidence concerning disciplined scholarly doubt", "الأدلة السياقية الخاصة بـ الشك العلمي المنضبط"),EnglishAdvancedWord("stakeholder engagement in disciplined scholarly doubt", "مشاركة أصحاب المصلحة في الشك العلمي المنضبط"),EnglishAdvancedWord("independent audit of disciplined scholarly doubt", "المراجعة المستقلة لـ الشك العلمي المنضبط"),EnglishAdvancedWord("policy implications of disciplined scholarly doubt", "الآثار على السياسات العامة لـ الشك العلمي المنضبط"),EnglishAdvancedWord("transnational perspectives on disciplined scholarly doubt", "المنظورات العابرة للحدود حول الشك العلمي المنضبط"),EnglishAdvancedWord("transparent dis